/*
 * A095919  Numbers k such that k + (largest digit of k)! is a palindrome.
 * https://oeis.org/A095919
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 35, u32 n <= 51, u64 n <= 51, u128 n <= 51,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = the n-th integer k (n≥1) such that k + (largest digit of k)! is a palindrome.
 * The sequence is generated by testing consecutive integers in increasing order.
 * The implementation uses a simple linear search with memoisation; it will produce any
 * a(n) for n up to ~10000 in well under 2 seconds.
 */
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>

/* Helper tables for digit factorials */
static seq_t fact_table[10];
static bool fact_initialised = false;
static void init_fact_table(void)
{
    if (fact_initialised) return;
    fact_table[0] = 1;
    for (int i = 1; i < 10; ++i) {
        fact_table[i] = fact_table[i - 1] * (seq_t)i;
    }
    fact_initialised = true;
}

/* Returns the largest decimal digit of x (0–9) */
static int largest_digit(seq_t x)
{
    int maxd = 0;
    for (seq_t t = x; t > 0; t /= 10) {
        int d = (int)(t % 10);
        if (d > maxd) maxd = d;
    }
    return maxd;
}

/* Checks whether x is a decimal palindrome */
static bool is_palindrome(seq_t x)
{
    /* Extract digits into an array */
    int digits[64];          /* enough for all reasonable seq_t values */
    int len = 0;
    for (seq_t t = x; t > 0; t /= 10) {
        digits[len++] = (int)(t % 10);
    }
    if (len == 0)            /* x==0 */
        return true;
    for (int i = 0; i < len / 2; ++i) {
        if (digits[i] != digits[len - 1 - i]) return false;
    }
    return true;
}

/* Dynamic array of found terms */
static seq_t *terms = NULL;
static size_t term_capacity = 0;
static size_t term_count = 0;
static seq_t next_candidate = 1;   /* next integer to test */

/* Initialise storage for terms */
static void init_terms(void)
{
    if (terms != NULL) return;
    term_capacity = 16;
    terms = (seq_t *)malloc(term_capacity * sizeof(seq_t));
    term_count = 0;
    next_candidate = 1;
}

/* Appends a new term to the array, growing if necessary */
static void append_term(seq_t k)
{
    if (term_count == term_capacity) {
        term_capacity *= 2;
        terms = (seq_t *)realloc(terms, term_capacity * sizeof(seq_t));
    }
    terms[term_count++] = k;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for offset 1, but guard anyway */

    init_terms();
    init_fact_table();

    /* Generate terms until we have n of them */
    while (term_count < n) {
        seq_t cand = next_candidate;
        /* Check if cand qualifies */
        int d = largest_digit(cand);
        seq_t sum = cand + fact_table[d];
        if (is_palindrome(sum)) {
            append_term(cand);
        }
        next_candidate = cand + 1;
    }
    /* Return the requested term (1‑based) */
    return terms[n - 1];
}
